import { Router } from 'express';
import fs from 'node:fs';
import path from 'node:path';
import { config } from '../lib/config.js';

/**
 * Tauri v2 updater endpoint.
 * tauri.conf.json -> plugins.updater.endpoints:
 *   https://api.yourdomain.com/api/v1/updates/{{target}}/{{arch}}/{{current_version}}
 * Place `latest.json` (generated by `tauri build` with createUpdaterArtifacts) in RELEASES_DIR.
 * Returns 204 when the client is up to date (Tauri treats this as "no update").
 */
export const updatesRouter = Router();

const cmp = (a: string, b: string) => {
  const pa = a.split('.').map(Number), pb = b.split('.').map(Number);
  for (let i = 0; i < 3; i++) if ((pa[i] ?? 0) !== (pb[i] ?? 0)) return (pa[i] ?? 0) - (pb[i] ?? 0);
  return 0;
};

updatesRouter.get('/:target/:arch/:current', (req, res) => {
  const file = path.join(config.releasesDir, 'latest.json');
  if (!fs.existsSync(file)) return res.status(204).end();
  const manifest = JSON.parse(fs.readFileSync(file, 'utf8'));
  if (cmp(String(manifest.version).replace(/^v/, ''), req.params.current) <= 0) return res.status(204).end();
  const key = `${req.params.target}-${req.params.arch}`;
  const platform = manifest.platforms?.[key];
  if (!platform) return res.status(204).end();
  res.json({ version: manifest.version, notes: manifest.notes, pub_date: manifest.pub_date, url: platform.url, signature: platform.signature });
});

updatesRouter.get('/latest.json', (_req, res) => {
  const file = path.join(config.releasesDir, 'latest.json');
  if (!fs.existsSync(file)) return res.status(404).json({ error: 'No release published' });
  res.sendFile(file);
});
